import {readAnswerQuality} from './answer-guard.js';
import {userInfo} from 'node:os';
import { readFileSync } from 'node:fs';

export const name = 'natural-data';
export const inject = ['webServer', 'connection', 'sessionController', 'workspaceRegistry'];
let endpoint = 'http://127.0.0.1:5671';
let token = process.env.NATURAL_DATA_TOKEN;
delete process.env.NATURAL_DATA_TOKEN;

// A packaged plugin owns its transport; the legacy launcher can still supply it.
export function configureTransport(value) {
  endpoint = value.endpoint;
  token = value.token;
}

export async function call(operation, project, args={}, request_key='', signal, session_id='', host_evidence={}) {
  if (!endpoint || !token) throw new Error('问数插件未启用或数据引擎不可用。');
  const response = await fetch(`${endpoint}/v1/${operation}`, {method:'POST', headers:{'content-type':'application/json', authorization:`Bearer ${token}`}, body:JSON.stringify({project,args,request_key,session_id,host_evidence,principal:process.env.NATURAL_WORK_PRINCIPAL||'local:'+userInfo().username}), signal});
  if (!response.ok) {const error = await response.json(); const failure=new Error(error.detail || '数据服务不可用');failure.status=response.status;throw failure;}
  return operation === 'export' ? response.text() : response.json();
}
export function apply(ctx) {
  ctx.effect(() => ctx.webServer.register({kind:'prefix',path:'/natural-data',async handler(req,res) {
    const rejection=ctx.connection.requestRejection({headers:req.headers});
    if(rejection){res.writeHead(typeof rejection === 'number' ? rejection : rejection.status || 401);res.end('Unauthorized');return;}
    const u = new URL(req.url,'http://localhost');
    try {
      if (u.pathname.startsWith('/natural-data/assets/')) {
        const file=u.pathname.slice('/natural-data/assets/'.length);
        if(!/^[a-zA-Z0-9_.-]+$/.test(file)){res.writeHead(404);res.end();return;}
        res.setHeader('Content-Type',file.endsWith('.css')?'text/css':'application/javascript');
        res.end(readFileSync(new URL('./assets/'+file,import.meta.url)));return;
      }
      if (u.pathname === '/natural-data/client.css') {res.setHeader('Content-Type','text/css');res.end(readFileSync(new URL('./style.css',import.meta.url)));return;}
      if (u.pathname === '/natural-data/view') {
        if (!u.searchParams.has('settings') && !u.searchParams.has('result_ref')) {res.writeHead(404);res.end('请在对话中使用问数模式。');return;}
        res.setHeader('Content-Type','text/html; charset=utf-8');res.setHeader('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'self'");
        res.end('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>问数结果 · 自然 Work</title><link rel="stylesheet" href="/natural-data/assets/result-app.css"></head><body><div id="root"></div><script type="module" src="/natural-data/assets/result-app.js"></script></body></html>');return;
      }
      if (u.pathname === '/natural-data/viewer.js') {res.setHeader('Content-Type','application/javascript');res.end(readFileSync(new URL('./viewer.js',import.meta.url)));return;}
      if(u.pathname==='/natural-data/api/answer-quality'){
        if(req.method!=='GET'){res.writeHead(405);res.end();return;}
        const value=readAnswerQuality(u.searchParams.get('session'),Number(u.searchParams.get('turn')));
        res.setHeader('Cache-Control','no-store');res.setHeader('Content-Type','application/json');res.end(JSON.stringify(value));return;
      }
      const op = u.pathname.split('/').pop();
      if(!['config','catalog','results','result','visualize','export','bind','sync','test','policy','policy_update','business_update','session_project','project_skills','connections','connection_test','connection_update','make_report','edit_report'].includes(op)) {res.writeHead(404);res.end();return;}
      if(req.method!=='GET' && req.method!=='POST') {res.writeHead(405);res.end();return;}
      if(['bind','visualize','sync','test','policy_update','business_update','connection_test','connection_update','make_report','edit_report'].includes(op) && req.method!=='POST') {res.writeHead(405);res.end();return;}
      if(['connections','connection_test','connection_update','make_report','edit_report'].includes(op) && u.search) {res.writeHead(422);res.end('连接配置必须放在请求正文中。');return;}
      if(op==='session_project' && req.method==='GET' && u.searchParams.has('business_project')) {res.writeHead(405);res.end();return;}
      let body={};
      if(req.method==='POST') {let raw='';for await(const part of req){raw+=part;if(raw.length>524288)throw new Error('请求过大');} body=JSON.parse(raw||'{}');}
      const project = body.project || u.searchParams.get('project') || '__operator__';
      const args={...Object.fromEntries(u.searchParams),...body};delete args.project;
      const value=await call(op,project,args);
      res.setHeader('Cache-Control','no-store');
      if(op==='export'){res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="natural-work-result.csv"');res.end(value);}
      else {res.setHeader('Content-Type','application/json');res.end(JSON.stringify(value));}
    } catch(error) {res.writeHead([403,409,422].includes(error.status)?error.status:422,{'Content-Type':'application/json'});res.end(JSON.stringify({error:error.message}));}
  }}));
}
